294			var graph map[string]*Lineage
295			if err := Register(graph, Dataset{Name: "A"}, nil); !errors.Is(err, ErrNotInitialized) {
296				t.Fatalf("err = %v, want ErrNotInitialized", err)
297			}
298		})
299	
300		t.Run("unknown upstream", func(t *testing.T) {
301			graph := map[string]*Lineage{}
302			err := Register(graph, Dataset{Name: "A"}, []string{"nope"})
303			if !errors.Is(err, ErrNotFound) {
304				t.Fatalf("err = %v, want ErrNotFound", err)
305			}
306		})
307	
308		t.Run("upstream pointing at nil node", func(t *testing.T) {
309			graph := map[string]*Lineage{"zombie": nil}
310			err := Register(graph, Dataset{Name: "A"}, []string{"zombie"})
311			if !errors.Is(err, ErrInvalidArgument) {
312				t.Fatalf("err = %v, want ErrInvalidArgument", err)
313			}
314			if _, exists := graph["A"]; exists {
315				t.Fatal("node created against nil upstream")
316			}
317		})
318	
319		t.Run("empty upstream name is not a registered node", func(t *testing.T) {
320			graph := map[string]*Lineage{}
321			err := Register(graph, Dataset{Name: "A"}, []string{""})
322			if !errors.Is(err, ErrNotFound) {
323				t.Fatalf("err = %v, want ErrNotFound", err)
324			}
325		})
326	}
327	
328	func TestRegisterPreservesNameCasingAndSpacing(t *testing.T) {
329		graph := map[string]*Lineage{}
330		mustRegister(t, graph, " Raw-Blocks ")
331		mustRegister(t, graph, "RAW-BLOCKS", " Raw-Blocks ")
332		if got := graph["RAW-BLOCKS"].Parents; !reflect.DeepEqual(got, []string{" Raw-Blocks "}) {
333			t.Fatalf("name was trimmed or case-folded: %v", got)
334		}
335	}
336	
337	func TestRootsStableOrder(t *testing.T) {
338		graph := map[string]*Lineage{}
339		mustRegister(t, graph, "zeta")
340		mustRegister(t, graph, "alpha")
341		mustRegister(t, graph, "mid", "alpha")
342		mustRegister(t, graph, "beta")
343		want := []string{"alpha", "beta", "zeta"}
344		for i := 0; i < 5; i++ {
345			if got := Roots(graph); !reflect.DeepEqual(got, want) {
346				t.Fatalf("Roots = %v, want %v", got, want)
347			}
348		}
349	}
350	
351	func dump(graph map[string]*Lineage) string {
352		s := "map["
353		for _, name := range Roots(graph) {
354			e := graph[name]
355			s += fmt.Sprintf("%s:{P:%v C:%v} ", name, e.Parents, e.Children)
356		}
357		// Include non-roots too, sorted by name so the dump is deterministic
358		// regardless of map iteration order.
359		var nonRoots []string
360		for name, e := range graph {
361			if len(e.Parents) != 0 {
362				nonRoots = append(nonRoots, name)
363			}
364		}
365		sort.Strings(nonRoots)
366		for _, name := range nonRoots {
367			e := graph[name]
368			s += fmt.Sprintf("%s:{P:%v C:%v} ", name, e.Parents, e.Children)
369		}
370		return s + "]"
371	}
