230		// Apply once, then again: the second apply is a no-op.
231		if _, err := ApplyBatch(graph, plan); err != nil {
232			t.Fatalf("first ApplyBatch unexpected error: %v", err)
233		}
234		snapshot := dump(graph)
235		report, err = ApplyBatch(graph, plan)
236		if err != nil {
237			t.Fatalf("second ApplyBatch unexpected error: %v", err)
238		}
239		if got := dump(graph); got != snapshot {
240			t.Fatalf("re-apply mutated graph:\n got %s\nwant %s", got, snapshot)
241		}
242		if len(report.ChangedDatasets) != 0 || len(report.AddedRelations) != 0 ||
243			len(report.RemovedRelations) != 0 || len(report.AffectedDownstreams) != 0 {
244			t.Errorf("re-apply produced non-empty diff: %+v", report)
245		}
246	}
