		}
		if name == "" {
			return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
		}
		records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
	}
	adj, err := normalizeDatasets(records)
	if err != nil {
